CREATE POLICY work_order_select ON public.work_order FOR SELECT TO authenticated USING (public.can_read_order(order_id));
--> statement-breakpoint
CREATE POLICY work_result_select ON public.work_result FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM work_order w WHERE w.id = work_order_id AND public.can_read_order(w.order_id)));
--> statement-breakpoint
CREATE POLICY work_photo_select ON public.work_photo FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM work_order w WHERE w.id = work_order_id AND public.can_read_order(w.order_id)));
--> statement-breakpoint
CREATE POLICY activity_log_select ON public.activity_log FOR SELECT TO authenticated USING (public.can_read_order(order_id));
